use std::collections::{HashMap,VecDeque};use std::env;use std::fs::{self,File};use std::io::{Read,Write};use std::net::{SocketAddr,TcpListener,TcpStream};use std::path::PathBuf;use std::sync::{Arc,Condvar,Mutex};use std::sync::atomic::{AtomicUsize,Ordering};use std::thread;use std::time::{Duration,Instant};
#[derive(Clone)]struct C{listen:SocketAddr,root:PathBuf,max:usize,limit:usize,timeout:Duration,write:Duration}struct J{s:TcpStream,t:Instant}type Q=Arc<(Mutex<VecDeque<J>>,Condvar)>;
fn config(p:&str)->Result<C,String>{let text=fs::read_to_string(p).map_err(|e|e.to_string())?;let mut m=HashMap::new();for(i,l)in text.lines().enumerate(){let x=l.trim();if x.is_empty()||x.starts_with('#'){continue}let(k,v)=x.split_once('=').ok_or(format!("line {}",i+1))?;let(k,v)=(k.trim(),v.trim());if k.is_empty()||v.is_empty()||!["listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth"].contains(&k){return Err("bad config".into())}if m.insert(k.to_owned(),v.to_owned()).is_some(){return Err("duplicate".into())}}for k in ["listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth"]{if !m.contains_key(k){return Err(format!("missing {k}"))}}fn num(m:&HashMap<String,String>,k:&str)->Result<usize,String>{let s=&m[k];if !s.bytes().all(|b|b.is_ascii_digit()){return Err("bad number".into())}let n=s.parse::<usize>().map_err(|_|"bad number")?;if n==0{return Err("zero limit".into())}Ok(n)}let listen=m["listen"].parse().map_err(|_|"bad address")?;let root=PathBuf::from(&m["root"]);if !root.is_absolute()||!fs::metadata(&root).map(|x|x.is_dir()).unwrap_or(false){return Err("bad root".into())}Ok(C{listen,root,max:num(&m,"max_connections")?,limit:num(&m,"header_bytes")?,timeout:Duration::from_millis(num(&m,"header_timeout_ms")? as u64),write:Duration::from_millis(num(&m,"write_timeout_ms")? as u64)})}
fn token(b:u8)->bool{b.is_ascii_alphanumeric()||b"!#$%&'*+-.^_`|~".contains(&b)}fn hex(b:u8)->Option<u8>{match b{b'0'..=b'9'=>Some(b-48),b'a'..=b'f'=>Some(b-87),b'A'..=b'F'=>Some(b-55),_=>None}}
fn path(t:&str)->Result<String,u16>{if t.contains('#')||!t.starts_with('/')||t.starts_with("//"){return Err(400)}let b=t.split('?').next().unwrap().as_bytes();let mut o=Vec::new();let mut i=0;while i<b.len(){if b[i]==37{if i+2>=b.len(){return Err(400)}o.push(hex(b[i+1]).ok_or(400u16)?*16+hex(b[i+2]).ok_or(400u16)?);i+=3}else{o.push(b[i]);i+=1}}let s=String::from_utf8(o).map_err(|_|400u16)?;if s.bytes().any(|b|b==0||b==92){return Err(400)}if s.split('/').any(|x|x==".."){return Err(403)}Ok(s)}
fn error(s:&mut TcpStream,n:u16){let r=match n{400=>"Bad Request",403=>"Forbidden",404=>"Not Found",405=>"Method Not Allowed",431=>"Request Header Fields Too Large",_=>"Error"};let _=write!(s,"HTTP/1.1 {n} {r}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");}
fn sendfile(s:&mut TcpStream,c:&C,p:&str){let mut q=c.root.clone();for x in p.split('/').filter(|x|!x.is_empty()){if x=="."{continue}if x==".."{error(s,403);return}q.push(x);match fs::symlink_metadata(&q){Ok(m)=>if m.file_type().is_symlink()||(!m.is_file()&&!m.is_dir()){error(s,403);return},Err(e)=>{error(s,if e.kind()==std::io::ErrorKind::NotFound{404}else{403});return}}}let m=match fs::symlink_metadata(&q){Ok(x)=>x,Err(e)=>{error(s,if e.kind()==std::io::ErrorKind::NotFound{404}else{403});return}};if !m.is_file()||(p.len()>1&&p.ends_with('/')){error(s,403);return}let mut f=match File::open(q){Ok(x)=>x,Err(_)=>{error(s,403);return}};if write!(s,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nContent-Type: application/octet-stream\r\nConnection: close\r\n\r\n",m.len()).is_ok(){let _=std::io::copy(&mut f,s);}}
fn header(s:&mut TcpStream,c:&C,t:Instant)->Result<Vec<u8>,u16>{let mut d=Vec::new();let mut b=[0u8;4096];loop{let elapsed=t.elapsed();if elapsed>=c.timeout{return Err(408)}let _=s.set_read_timeout(Some(c.timeout-elapsed));match s.read(&mut b){Ok(0)=>return Err(400),Ok(n)=>{d.extend_from_slice(&b[..n]);if let Some(i)=d.windows(4).position(|x|x==b"\r\n\r\n"){if i+4>c.limit{return Err(431)}d.truncate(i+4);return Ok(d)}if d.len()>c.limit{return Err(431)}if d.iter().enumerate().any(|(i,x)|*x==10&&(i==0||d[i-1]!=13)){return Err(400)}},Err(e)if e.kind()==std::io::ErrorKind::TimedOut||e.kind()==std::io::ErrorKind::WouldBlock=>return Err(408),Err(_)=>return Err(400)}}}
fn parse(d:&[u8])->Result<(String,String),u16>{if d.contains(&0){return Err(400)}let t=std::str::from_utf8(d).map_err(|_|400u16)?;if t.len()<4{return Err(400)}let l:Vec<&str>=t[..t.len()-4].split("\r\n").collect();let p:Vec<&str>=l[0].split(' ').collect();if p.len()!=3||p.iter().any(|x|x.is_empty())||!p[0].bytes().all(token)||p[1].bytes().any(|x|x<=32||x==127){return Err(400)}if p[2]!="HTTP/1.0"&&p[2]!="HTTP/1.1"{return Err(400)}let mut cl=0;for x in l.iter().skip(1){if x.is_empty()||x.starts_with(' ')||x.starts_with('\t'){return Err(400)}let(n,v)=x.split_once(':').ok_or(400u16)?;if n.is_empty()||!n.bytes().all(token)||v.bytes().any(|b|(b<32&&b!=9)||b==127){return Err(400)}if n.eq_ignore_ascii_case("transfer-encoding"){return Err(400)}if n.eq_ignore_ascii_case("content-length"){cl+=1;if cl>1{return Err(400)}let v=v.trim();if v.is_empty()||!v.bytes().all(|b|b.is_ascii_digit())||v.parse::<u64>().map_err(|_|400u16)?!=0{return Err(400)}}}Ok((p[0].to_owned(),p[1].to_owned()))}
fn serve(mut s:TcpStream,c:Arc<C>,t:Instant){let _=s.set_write_timeout(Some(c.write));match header(&mut s,&c,t){Err(431)=>error(&mut s,431),Err(400)=>error(&mut s,400),Err(_)=>{},Ok(d)=>match parse(&d){Err(n)=>error(&mut s,n),Ok((m,u))=>if m!="GET"{error(&mut s,405)}else{match path(&u){Err(n)=>error(&mut s,n),Ok(p)=>sendfile(&mut s,&c,&p)}}}}}
fn main(){let a:Vec<String>=env::args().collect();let mut p=None;let mut i=1;while i<a.len(){if a[i]=="--config"&&i+1<a.len(){p=Some(a[i+1].clone());i+=2}else{std::process::exit(2)}}let c=match config(p.as_deref().unwrap_or("/fixtures/server.conf")){Ok(x)=>x,Err(e)=>{eprintln!("{e}");std::process::exit(2)}};let l=match TcpListener::bind(c.listen){Ok(x)=>x,Err(e)=>{eprintln!("{e}");std::process::exit(1)}};let c=Arc::new(c);let q:Q=Arc::new((Mutex::new(VecDeque::new()),Condvar::new()));let n=Arc::new(AtomicUsize::new(0));for _ in 0..32.min(c.max){let(q,c,n)=(q.clone(),c.clone(),n.clone());thread::spawn(move||loop{let j={let(m,v)=&*q;let mut g=m.lock().unwrap();while g.is_empty(){g=v.wait(g).unwrap()}g.pop_front().unwrap()};serve(j.s,c.clone(),j.t);n.fetch_sub(1,Ordering::Relaxed);});}for r in l.incoming(){if let Ok(s)=r{if n.fetch_add(1,Ordering::Relaxed)>=c.max{n.fetch_sub(1,Ordering::Relaxed);drop(s);continue}let(m,v)=&*q;m.lock().unwrap().push_back(J{s,t:Instant::now()});v.notify_one()}}}
